import numpy as np, tfd, warnings; warnings.filterwarnings("ignore")
import ground as G
from hfs import L
from t7c_kernel import numerov_wf_sr, _derivs, C0
def split(occ):
    up,dn=[],[]
    for n,l,k in occ:
        ku=min(k,2*l+1); kd=k-ku
        if ku: up.append((n,l,ku))
        if kd: dn.append((n,l,kd))
    return up,dn
def scf_pol_sr(Z, charge=1, occ=None, c=C0, npts=4000, beta=0.3, tol=2e-5, maxit=80):
    N=Z-charge; q=charge
    if occ is None: occ=list(G.expand(N)) if N>0 else []
    up,dn=split(occ)
    x=np.linspace(np.log(1e-6/Z),np.log(300.0),npts); r=np.exp(x); h=x[1]-x[0]; dr=r*h
    Vt,_=tfd.potential(Z,charge); Vg={s:Vt(r).copy() for s in "ud"}
    def mk(V):
        Vp,Vpp=_derivs(x,V)
        return (lambda rr,V=V:np.interp(np.log(np.asarray(rr,float)),x,V)),(lambda rr,V=Vp:np.interp(np.log(np.asarray(rr,float)),x,V)),(lambda rr,V=Vpp:np.interp(np.log(np.asarray(rr,float)),x,V))
    Vf={s:mk(Vg[s]) for s in "ud"}
    hist=[]
    for it in range(maxit):
        nsig={}; Es={}
        for s,lst in (("u",up),("d",dn)):
            n_r=np.zeros(npts)
            for n,l,k in lst:
                rr,drr,u,E,nd=numerov_wf_sr(Vf[s][0],l,n,1.0,Z,c,Vp=Vf[s][1],Vpp=Vf[s][2])
                if nd!=n-l-1: raise RuntimeError(f"Z={Z} {n}{L[l]}{s} nodes {nd}")
                ui=np.interp(r,rr,u,left=0.0,right=0.0); ui/=np.sqrt(np.sum(ui*ui*dr))
                n_r+=k*ui*ui; Es[(n,l,s)]=E
            nsig[s]=n_r
